schemas.schema-01-actors.prisma:
/// Temporary guest accounts identified by device fingerprint for anonymous
/// access before registration.
///
/// This table represents guest actors who have not yet registered but need
/// temporary identity tracking. Each guest is uniquely identified by their
/// device fingerprint, which persists across sessions until the user either
/// registers as a member or the guest account is cleaned up.
///
/// Guest accounts are temporary and intended for anonymous users exploring
/// the application before committing to registration. The device fingerprint
/// serves as the primary identification mechanism, allowing the system to
/// maintain session continuity and track guest activity without requiring
/// email/password credentials.
///
/// Related entities:
/// - {@link todo_app_guest_sessions} - Multiple sessions can exist for each
/// guest account
/// - {@link todo_app_members} - Guests can upgrade to member accounts
/// through registration
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_guests {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique device identifier for guest recognition across sessions.
  device_fingerprint String

  /// Timestamp when the guest account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the guest account was soft deleted, null if active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions todo_app_guest_sessions[]

  //----
  // INDEXES
  //----
  @@unique([device_fingerprint])
  @@index([created_at])
}

/// Temporary session tokens for guest access with expiration tracking.
///
/// This table records login sessions for guest actors, storing connection
/// metadata and temporal information for security auditing. Sessions are
/// append-only and track the guest's access period through expiration
/// timestamps.
///
/// Related to {@link todo_app_guests} through a 1:N relationship where one
/// guest can have multiple active or expired sessions.
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_guest_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Belonged guest's {@link todo_app_guests.id}.
  todo_app_guest_id String @db.Uuid

  /// IP address of the client connection.
  ip String

  /// URL href where the session was initiated.
  href String

  /// Referrer URL from the client request.
  referrer String

  /// Session creation timestamp.
  created_at DateTime @db.Timestamptz

  /// Session expiration timestamp for security lifecycle management.
  expired_at DateTime @db.Timestamptz

  //----
  // BELONGED RELATIONS,
  //   - format: (propertyKey targetModel constraint)
  //----
  guest todo_app_guests @relation(fields: [todo_app_guest_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@index([todo_app_guest_id, created_at])
}

/// Registered member accounts with email/password credentials and profile
/// information.
///
/// This table serves as the primary identity record for authenticated users
/// in the todo application. Each member has a unique email address for
/// authentication and a display name for their profile. Members own private
/// todos and can manage their account settings including password changes
/// and account deletion.
///
/// Related entities:
/// - {@link todo_app_member_sessions} - Login sessions for this member
/// (many-to-one)
/// - {@link todo_app_member_password_resets} - Password reset tokens
/// (many-to-one)
/// - {@link todo_app_member_email_verifications} - Email verification tokens
/// (many-to-one)
/// - {@link todo_app_todos} - Todos owned by this member (many-to-one)
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model todo_app_members {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Unique email address used for authentication and account identification.
  email String

  /// Bcrypt hashed password for secure authentication. Never store plain text
  /// passwords.
  password_hash String

  /// User's display name shown in their profile and todo listings.
  display_name String

  /// Timestamp when the member account was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when the member account was last updated.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the member account was soft deleted. Null if account is
  /// active.
  deleted_at DateTime? @db.Timestamptz

  //----
  // HAS RELATIONS
  //   - format: (propertyKey targetModel)
  //----
  sessions todo_app_member_sessions[]
  passwordResets todo_app_member_password_resets[]
  emailVerifications todo_app_member_email_verifications[]
  todos todo_app_todos[]

  //----
  // INDEXES
  //----
  @@unique([email])
  @@index([created_at])
  @@index([display_name(ops: raw("gin_trgm_ops"))], type: Gin)
}

