  member todo_app_members @relation(fields: [todo_app_member_id], references: [id], onDelete: Cascade)

  //----
  // INDEXES
  //----
  @@unique([token])
  // spellchecker: ignore-next-line
  @@index([todo_app_member_id, created_at], map: "todo_app_member_password_resets_todo_app_member_id_cre_ec559a42")
  @@index([expired_at])
}

/// Email verification tokens for account registration and email confirmation.
///
/// Stores verification tokens sent to members during registration or email
/// address changes. Each token has an expiration time and tracks when (if)
