  typia.assert(sortedByDueDesc);
  const nullDueAtIndicesDesc: number[] = [];
  const nonNullDueAtIndicesDesc: number[] = [];
  sortedByDueDesc.data.forEach((todo, index) => {
    if (todo.due_at === null) {
      nullDueAtIndicesDesc.push(index);
