 *
 * Workflow:
 * 1. Member joins and authenticates
 * 2. Member creates a todo with title, description, start date, and due date
 * 3. Member soft-deletes the todo (moves to trash)
 * 4. Member restores the todo from trash
 * 5. Validate restored todo has all original properties intact
 */
export async function test_api_todo_restore_from_trash_success(
  connection: api.IConnection,
): Promise<void> {
  // 1. Member authentication
  const memberConnection: api.IConnection = { host: connection.host };
  const memberAuth: ITodoAppMember.IAuthorized = await authorize_member_join(
    memberConnection,
    {
      body: {
        email: typia.random<string & tags.Format<"email">>(),
        password: RandomGenerator.alphaNumeric(16),
        display_name: RandomGenerator.name(),
        href: typia.random<string & tags.Format<"uri">>(),
        referrer: typia.random<string & tags.Format<"uri">>(),
        ip: typia.random<string & tags.Format<"ipv4">>(),
      } satisfies ITodoAppMember.IJoin,
    },
  );
  typia.assert(memberAuth);
  // 2. Create a todo with all optional fields
  const originalTodo: ITodoAppTodo =
    await generate_random_todo_app_member_todos_create(memberConnection, {
      body: {
        title: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.content({ paragraphs: 2 }),
        started_at: new Date().toISOString(),
        due_at: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000).toISOString(),
      } satisfies ITodoAppTodo.ICreate,
    });
  typia.assert(originalTodo);
  // Verify newly created todo is incomplete by default
  TestValidator.predicate(
    "new todo is incomplete",
    originalTodo.completed === false,
  );
  // 3. Soft-delete the todo (move to trash)
  await api.functional.todoApp.member.todos.erase(memberConnection, {
    todoId: originalTodo.id,
  });
  // 4. Restore the todo from trash
  const restoredTodo: ITodoAppTodo =
    await api.functional.todoApp.member.todos.trash.restore(memberConnection, {
      todoId: originalTodo.id,
    });
  typia.assert(restoredTodo);
  // 5. Validate restored todo properties
  TestValidator.equals("todo id matches", restoredTodo.id, originalTodo.id);
  TestValidator.equals(
    "title preserved",
    restoredTodo.title,
    originalTodo.title,
  );
  TestValidator.equals(
    "description preserved",
    restoredTodo.description,
    originalTodo.description,
  );
  TestValidator.equals(
    "started_at preserved",
    restoredTodo.started_at,
    originalTodo.started_at,
  );
  TestValidator.equals(
    "due_at preserved",
    restoredTodo.due_at,
    originalTodo.due_at,
  );
  TestValidator.equals(
    "completed status preserved",
    restoredTodo.completed,
    originalTodo.completed,
  );
  TestValidator.equals(
    "created_at unchanged",
    restoredTodo.created_at,
    originalTodo.created_at,
  );
  TestValidator.predicate(
    "completed is false",
    restoredTodo.completed === false,
  );
}

import api from "@ORGANIZATION/PROJECT-api";
