    data: updateData,
  });
  // Fetch the updated record with transformer select
  const updated = await MyGlobal.prisma.todo_app_members.findUniqueOrThrow({
    where: {
      id: props.member.id,
    },
    ...TodoAppMemberTransformer.select(),
  });
